// ZERO MILE — iDos Games Cloud Code: the authority over a driver's progression.
//
// Generated by scripts/idos-config.ts from idos/cloudcode.template.js — edit the template, not this file.

var TABLES = {"vehicles":{"rammer":160,"ghost":260,"hauler":360},"unlocks":{"pack_fire":{"price":110,"levels":1},"pack_electric":{"price":110,"levels":1},"pack_legend":{"price":200,"levels":1},"ab_boost":{"price":60,"levels":1},"ab_harpoon":{"price":80,"levels":1},"ab_repair":{"price":100,"levels":1},"ab_phase":{"price":120,"levels":1},"ev_blackmarket":{"price":90,"levels":1},"perk_hp":{"price":60,"levels":3},"perk_credits":{"price":50,"levels":2},"perk_reroll":{"price":70,"levels":1},"perk_momentum":{"price":60,"levels":1}},"paints":{"crimson":40,"acid":40,"void":60,"gold":80,"chrome":120},"salvageMul":[1,1.4,1.8],"difficultyNames":["NIGHT ONE","DEEP NIGHT","BLACKOUT"],"lore":["lore_intro","lore_zero","lore_driver","lore_garage","lore_courier","lore_signal","lore_scrap","lore_broadcast","lore_mule","lore_bus","lore_taxon","lore_apex","lore_end"],"runCap":1500,"eventSalvageCap":60,"maxMetresPerSecond":80,"legacyCap":2500,"huntReportCap":9000,"huntCooldownMs":40000,"insuranceBoost":"use_insurance","insuranceWindowMs":600000};
var SV = 'SV';
var MONDAY_EPOCH = Date.UTC(1970, 0, 5);
var WEEK_MS = 7 * 24 * 3600 * 1000;

// ---------------------------------------------------------------- helpers

function fail(code, extra) {
  var r = { ok: false, error: code };
  if (extra) for (var k in extra) r[k] = extra[k];
  return r;
}

function customData() {
  var r = server.GetUserCustomData();
  if (!r.Success) throw new Error(r.Error);
  return r.Data || {};
}

function readJson(bucket, key, data) {
  var b = (data || customData())[bucket] || {};
  if (!b[key] || !b[key].Value) return null;
  try {
    return JSON.parse(b[key].Value);
  } catch (e) {
    return null;
  }
}

function defaultProfile() {
  return { best: { distance: 0, kills: 0, zone: 0, maxSpeed: 0, combo: 0, score: 0, won: false }, runs: 0, wins: 0, totalSalvage: 0, maxDifficulty: 0, lore: ['lore_intro'], tutorialDone: false };
}

function inventory() {
  var u = server.ReadUserData(['InventoryV2']);
  return (u && u.InventoryV2) || {};
}

function count(inv, itemId) {
  var t = inv.Items && inv.Items[itemId];
  return t ? t.TotalAmount || t.StackableAmount || 0 : 0;
}

function salvage(inv) {
  var v = inv.VirtualCurrencies && inv.VirtualCurrencies[SV];
  return v ? v.Amount : 0;
}

function item(id, amount) {
  return { Type: 'Item', CatalogID: 'garage', ItemID: id, Amount: amount || 1 };
}

function sv(amount) {
  return { Type: 'VirtualCurrency', CurrencyID: SV, Amount: amount };
}

/** a reason no other operation has: the platform treats a repeated Reason as a replay and skips it */
function once(prefix) {
  return prefix + '_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

/** one atomic charge and/or grant; refuses as a whole. `reason` must be unique per operation (see once). */
function apply(consume, grant, reason) {
  var op = {};
  if (consume.length) op.Consume = { Standard: { Entries: consume } };
  if (grant.length) op.Grant = { Standard: { Entries: grant } };
  var r = server.ApplyResourceOperation({ Operation: op, Reason: reason });
  return r && r.Success ? null : (r && r.Error) || 'refused';
}

function num(v, lo, hi) {
  v = Number(v);
  if (!isFinite(v)) return lo;
  return Math.max(lo, Math.min(hi, v));
}

// ---------------------------------------------------------------- a run

/** open a run: the ticket finishRun must present, and the clock it is checked against */
handlers.startRun = function (args, context) {
  var diff = Math.floor(num(args && args.difficulty, 0, 2));
  var profile = readJson('ReadOnly', 'profile') || defaultProfile();
  if (diff > profile.maxDifficulty) return fail('difficulty_locked');
  var ticket = { id: Math.random().toString(36).slice(2) + Date.now().toString(36), at: Date.now(), diff: diff, ranked: !!(args && args.ranked) };
  var w = server.SetUserCustomData('Internal', 'run', JSON.stringify(ticket));
  if (!w.Success) throw new Error(w.Error);
  return { ok: true, ticket: ticket.id };
};

/**
 * close a run: check the numbers against the clock and the rules, pay the salvage, keep the records.
 * args: { ticket, won, stats: { distance, kills, bosses, zone, time, maxSpeed, combo, score, nodes }, eventSalvage, lore: [] }
 */
handlers.finishRun = function (args, context) {
  var data = customData();
  var ticket = readJson('Internal', 'run', data);
  if (!ticket || !args || args.ticket !== ticket.id) return fail('no_open_run');
  var del = server.DeleteUserCustomData('Internal', 'run');
  if (!del.Success) throw new Error(del.Error);

  var now = Date.now();
  var real = (now - ticket.at) / 1000;
  var s = args.stats || {};
  var time = num(s.time, 0, 6 * 3600);
  // the run's own clock can never be ahead of the real one (pauses only make it shorter)
  if (time > real + 20) return fail('clock');
  var zone = Math.floor(num(s.zone, 0, 4));
  var bosses = Math.floor(num(s.bosses, 0, zone + 1));
  var distance = num(s.distance, 0, time * TABLES.maxMetresPerSecond + 400);
  var kills = Math.floor(num(s.kills, 0, distance / 20 + 40));
  var won = !!args.won && zone === 4 && bosses >= 5;

  var mul = TABLES.salvageMul[ticket.diff] || 1;
  var pay = Math.round((distance / 130 + kills * 1.5 + bosses * 40 + zone * 20 + (won ? 150 : 0)) * mul);
  pay += Math.floor(num(args.eventSalvage, 0, TABLES.eventSalvageCap));
  pay = Math.min(pay, TABLES.runCap);

  var p = readJson('ReadOnly', 'profile', data) || defaultProfile();
  var notes = [];
  var inv = inventory();
  var grant = [];
  if (pay > 0) grant.push(sv(pay));
  p.runs += 1;
  p.totalSalvage += pay;
  p.best.distance = Math.max(p.best.distance, Math.round(distance));
  p.best.kills = Math.max(p.best.kills, kills);
  p.best.zone = Math.max(p.best.zone, zone);
  p.best.maxSpeed = Math.max(p.best.maxSpeed, Math.round(num(s.maxSpeed, 0, 420)));
  p.best.combo = Math.max(p.best.combo, Math.floor(num(s.combo, 0, 9999)));
  p.best.score = Math.max(p.best.score, Math.floor(num(s.score, 0, 50000000)));
  if (num(s.nodes, 0, 999) > 0 || won) p.tutorialDone = true;
  if (won) {
    p.wins += 1;
    p.best.won = true;
    if (ticket.diff >= p.maxDifficulty && p.maxDifficulty < 2) {
      p.maxDifficulty += 1;
      notes.push('NEW DIFFICULTY: ' + TABLES.difficultyNames[p.maxDifficulty]);
    }
    if (!count(inv, 'up_pack_legend')) {
      grant.push(item('up_pack_legend'));
      notes.push('LEGENDARY CACHE unlocked for free');
    }
    if (!count(inv, 'paint_gold')) {
      grant.push(item('paint_gold'));
      notes.push('NIGHT GOLD paint');
    }
  }
  var lore = args.lore || [];
  for (var i = 0; i < lore.length && i < 12; i++) if (TABLES.lore.indexOf(lore[i]) >= 0 && p.lore.indexOf(lore[i]) < 0) p.lore.push(lore[i]);

  if (grant.length) {
    var err = apply([], grant, 'run_' + ticket.id);
    if (err) return fail('grant', { detail: err });
  }
  var w = server.SetUserCustomData('ReadOnly', 'profile', JSON.stringify(p));
  if (!w.Success) throw new Error(w.Error);
  // what wreck insurance may pay out on, for a few minutes
  server.SetUserCustomData('Internal', 'last_run', JSON.stringify({ id: ticket.id, pay: pay, won: won, at: now, insured: false }));
  return { ok: true, salvage: pay, notes: notes, profile: p, ranked: ticket.ranked };
};

/**
 * wreck insurance: the run that just ended in a wreck pays its salvage a second time. The policy is the insurance
 * supply spent on the road (a timed boost, from stock or bought on the spot): it must have been taken out after the run
 * closed, and one policy covers one run.
 */
handlers.insureRun = function (args, context) {
  var data = customData();
  var last = readJson('Internal', 'last_run', data);
  if (!last || last.won || !(last.pay > 0)) return fail('nothing_to_insure');
  if (last.insured) return fail('already_insured');
  var now = Date.now();
  if (now - last.at > TABLES.insuranceWindowMs) return fail('expired');
  var u = server.ReadUserData(['TimedBoost']);
  var active = (u && u.TimedBoost && u.TimedBoost.Active) || {};
  var policy = null;
  for (var k in active) {
    var b = active[k];
    if (b && b.BoostID === TABLES.insuranceBoost && Date.parse(b.ActivatedAtUtc) >= last.at - 2000) {
      policy = b;
      break;
    }
  }
  if (!policy) return fail('no_policy');
  var err = apply([], [sv(last.pay)], 'insurance_' + last.id);
  if (err) return fail('grant', { detail: err });
  last.insured = true;
  server.SetUserCustomData('Internal', 'last_run', JSON.stringify(last));
  return { ok: true, salvage: last.pay };
};

// ---------------------------------------------------------------- the garage

/** buy with salvage: a car, an upgrade level, a paint. One atomic charge and grant. args: { kind, id } */
handlers.garageBuy = function (args, context) {
  var kind = args && args.kind, id = args && args.id;
  var inv = inventory();
  var price = 0, itemId = '';
  if (kind === 'vehicle') {
    price = TABLES.vehicles[id];
    itemId = 'car_' + id;
    if (!price) return fail('unknown');
    if (count(inv, itemId)) return fail('owned');
  } else if (kind === 'unlock') {
    var u = TABLES.unlocks[id];
    if (!u) return fail('unknown');
    itemId = 'up_' + id;
    var lvl = count(inv, itemId);
    if (lvl >= u.levels) return fail('owned');
    price = u.price * (lvl + 1);
  } else if (kind === 'paint') {
    price = TABLES.paints[id];
    itemId = 'paint_' + id;
    if (!price) return fail('unknown');
    if (count(inv, itemId)) return fail('owned');
  } else return fail('unknown');
  if (salvage(inv) < price) return fail('funds');
  var err = apply([sv(price)], [item(itemId)], once(itemId));
  if (err) return fail('refused', { detail: err });
  return { ok: true, item: itemId, price: price };
};

/**
 * the driver's records (ReadOnly profile) and public name, for a fresh client. A resumed session's state does not
 * always carry the public data, so the name comes from here.
 */
handlers.profile = function (args, context) {
  var u = server.ReadUserData(['PublicData']);
  var pub = (u && u.PublicData) || {};
  return { ok: true, profile: readJson('ReadOnly', 'profile') || defaultProfile(), name: pub.Username || '' };
};

/**
 * once per account: bring a pre-account save (the browser-only v1.0 game) onto the account. Only a fresh account can
 * import, only things the game sells, salvage capped.
 */
handlers.importLegacy = function (args, context) {
  var data = customData();
  if (readJson('Internal', 'legacy', data)) return fail('done');
  var p = readJson('ReadOnly', 'profile', data) || defaultProfile();
  if (p.runs > 0) return fail('not_fresh');
  var s = (args && args.save) || {};
  var grant = [];
  var cars = s.unlockedVehicles || [];
  for (var i = 0; i < cars.length; i++) if (TABLES.vehicles[cars[i]]) grant.push(item('car_' + cars[i]));
  var ups = s.unlocks || {};
  for (var k in ups) if (TABLES.unlocks[k]) {
    var n = Math.floor(num(ups[k], 0, TABLES.unlocks[k].levels));
    if (n > 0) grant.push(item('up_' + k, n));
  }
  var paints = s.paints || [];
  for (var j = 0; j < paints.length; j++) if (TABLES.paints[paints[j]]) grant.push(item('paint_' + paints[j]));
  var coins = Math.floor(num(s.salvage, 0, TABLES.legacyCap));
  if (coins > 0) grant.push(sv(coins));
  var b = s.best || {};
  p.best = { distance: Math.round(num(b.distance, 0, 1e6)), kills: Math.floor(num(b.kills, 0, 1e5)), zone: Math.floor(num(b.zone, 0, 4)), maxSpeed: Math.round(num(b.maxSpeed, 0, 420)), combo: Math.floor(num(b.combo, 0, 9999)), score: Math.floor(num(b.score, 0, 5e7)), won: !!b.won };
  p.runs = Math.floor(num(s.runs, 0, 1e5));
  p.wins = Math.floor(num(s.wins, 0, p.runs));
  p.totalSalvage = Math.floor(num(s.totalSalvage, 0, 1e9));
  p.maxDifficulty = Math.floor(num(s.maxDifficultyUnlocked, 0, 2));
  p.tutorialDone = !!s.tutorialDone;
  var lore = s.lore || [];
  for (var l = 0; l < lore.length && l < 40; l++) if (TABLES.lore.indexOf(lore[l]) >= 0 && p.lore.indexOf(lore[l]) < 0) p.lore.push(lore[l]);
  if (grant.length) {
    var err = apply([], grant, once('legacy'));
    if (err) return fail('grant', { detail: err });
  }
  server.SetUserCustomData('ReadOnly', 'profile', JSON.stringify(p));
  server.SetUserCustomData('Internal', 'legacy', JSON.stringify({ at: Date.now() }));
  return { ok: true, profile: p, salvage: coins, items: grant.length };
};

// ---------------------------------------------------------------- THE DRIVER hunt

function huntKey(now) {
  return 'hunt_w' + Math.floor((now - MONDAY_EPOCH) / WEEK_MS);
}

handlers.huntHit = function (args, context) {
  var dmg = Math.floor(num(args && args.damage, 0, TABLES.huntReportCap));
  if (dmg <= 0) return fail('nothing_to_report');
  var now = Date.now();
  var last = readJson('Internal', 'hunt_last');
  if (last && now - last < TABLES.huntCooldownMs) return fail('cooldown', { retryInMs: TABLES.huntCooldownMs - (now - last) });
  var mark = server.SetUserCustomData('Internal', 'hunt_last', String(now));
  if (!mark.Success) throw new Error(mark.Error);
  var key = huntKey(now);
  var inc = server.IncrementTitleCustomData('Public', key, dmg);
  if (!inc.Success) throw new Error(inc.Error);
  return { ok: true, key: key, added: dmg };
};

handlers.huntKey = function () {
  return { key: huntKey(Date.now()) };
};
